    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    box-shadow:
        0 20px 48px rgba(0, 0, 0, 0.45),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.dropdown-menu__content {
    margin: 0;
    padding: 4px 0;
    list-style: none;
    overflow-y: auto;
    flex: 1;
    font-size: 0.875rem;
    font-weight: 500;
    color: #e4e4e4;
    text-align: left;
}

