.services-overview-container {
    width: 345px;
    height: auto;
    max-height: 600px;
    overflow: hidden;
    border-radius: 10px;
    float: right;
    position: absolute;
    top: 60px;
    right: 20px;
    box-sizing: border-box;
    background: rgba(255, 255, 255, 0.8);
    box-shadow: 0 0 3px 0 rgba(0, 0, 0, 0.22), inset -1px 1px 1px rgba(255, 255, 255, 0.5);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
}

/* Account dropdown — aligned with dashboard dark UI + login gold accents */
.ia-menu.user_content {
    width: min(calc(100vw - 32px), 320px);
    max-height: min(90vh, 640px);
    overflow: hidden;
    border-radius: 14px;
    float: right;
    position: absolute;
    top: 60px;
    right: 20px;
    box-sizing: border-box;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
    background: linear-gradient(168deg, rgba(48, 48, 52, 0.98) 0%, rgba(24, 24, 28, 0.99) 100%);
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow:
        0 24px 56px rgba(0, 0, 0, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
}

.ia-menu__accent {
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 38%;
    max-width: 120px;
    height: 3px;
    border-radius: 0 0 8px 8px;
    background: linear-gradient(90deg, transparent, rgba(192, 159, 83, 0.9), transparent);
    pointer-events: none;
}

.ia-menu__body {
    padding: 22px 18px 12px;
    max-height: calc(min(90vh, 640px) - 76px);
    overflow-y: auto;
    text-align: center;
}

.ia-menu__brand {
    margin-bottom: 14px;
}

.ia-menu__brand-logo {
    display: block;
    width: min(160px, 72%);
    height: auto;
    margin: 0 auto;
    opacity: 0.92;
    filter: brightness(0) invert(1);
}

.ia-menu__avatar-wrap {
    position: relative;
    width: max-content;
    margin: 0 auto 16px;
}

.ia-menu__avatar {
    width: 88px;
    height: 88px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
    border: 3px solid rgba(192, 159, 83, 0.35);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.ia-menu__identity {
    color: #e8e8e8;
}

.ia-menu__greeting {
    margin: 0 0 4px;
    font-size: 1rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: #f0f0f0;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ia-menu__email {
    margin: 0 0 14px;
    font-size: 0.8125rem;
    line-height: 1.4;
    color: #9aa0a6;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ia-menu__manage {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 10px 14px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(0, 0, 0, 0.25);
    color: #d8d8d8 !important;
    font-size: 0.8125rem;
    font-weight: 500;
    text-decoration: none;
    text-align: left;
    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        color 0.2s ease;
    box-sizing: border-box;
}

.ia-menu__manage:hover {
    border-color: rgba(192, 159, 83, 0.45);
    background: rgba(192, 159, 83, 0.1);
    color: #f4f4f4 !important;
}

.ia-menu__manage-icon {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    object-fit: contain;
}

.ia-menu__workspace-panel {
    margin-top: 16px;
    padding: 12px 14px 12px;
    text-align: left;
    border-radius: 10px;
    border: 1px solid rgba(192, 159, 83, 0.22);
    background: linear-gradient(
        165deg,
        rgba(192, 159, 83, 0.08) 0%,
        rgba(0, 0, 0, 0.32) 58%
    );
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.ia-menu__workspace-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
}

.ia-menu__workspace-copy {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    min-width: 0;
    flex: 1;
}

.ia-menu__workspace-kicker {
    display: block;
    margin: 0;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #c0a053;
    line-height: 1.25;
}

.ia-menu__demo-label {
    display: block;
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 600;
    letter-spacing: 0.01em;
    color: #ececec;
    line-height: 1.3;
}

.ia-menu__demo-hint {
    margin: 0;
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 0.6875rem;
    line-height: 1.45;
    color: #8b9199;
}

.ia-menu__switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.ia-menu__switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.ia-menu__switch-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: rgba(255, 255, 255, 0.12);
    transition: background 0.25s ease;
    border-radius: 34px;
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.ia-menu__switch-slider::before {
    position: absolute;
    content: "";
    height: 18px;
    width: 18px;
    left: 3px;
    bottom: 2px;
    background: #f0f0f0;
    transition: transform 0.25s ease;
    border-radius: 50%;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
}

.ia-menu__switch input:checked + .ia-menu__switch-slider {
    background: rgba(192, 159, 83, 0.35);
    border-color: rgba(192, 159, 83, 0.5);
}

.ia-menu__switch input:checked + .ia-menu__switch-slider::before {
    transform: translateX(20px);
    background: #e8d5a8;
}

.ia-menu__switch input:focus-visible + .ia-menu__switch-slider {
    outline: 2px solid rgba(192, 159, 83, 0.7);
    outline-offset: 2px;
}

.ia-menu__footer {
    padding: 14px 16px 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.2);
}

.ia-menu__sign-out {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin: 0;
    padding: 11px 16px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.04);
    color: #c9cdd3;
    font-size: 0.875rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    transition:
        border-color 0.2s ease,
        background 0.2s ease,
        color 0.2s ease;
}

.ia-menu__sign-out:hover {
    border-color: rgba(220, 100, 100, 0.45);
    background: rgba(220, 80, 80, 0.12);
    color: #f0c4c4;
}

.ia-menu__sign-out-icon {
    flex-shrink: 0;
    opacity: 0.9;
}

.dropdown-links {
    max-height: 140px;
    height: auto;
    overflow: scroll;
}

.dropdown-links a {
    color: #000;
    font-size: 15px;
    padding: 15px;
    display: block;
    text-decoration: none;
}

.dropdown-links a:hover {
    background: #b7b7b7;
    text-decoration: none;
    color: #000;
}

@media screen and (min-width: 320px) and (max-width: 900px) {
    .ia-menu.user_content,
    .services-overview-container {
        top: 60px;
        right: 10px;
    }
}
